29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "postcode")
49	    @Pattern(regexp = "^[0-9]{4}$", message = "Postcode must be 4 digits")
50	    private String postcode;
51	
52	    @Column(name = "telephone")
53	    @NotEmpty
54	    @Pattern(regexp = "^\\+[0-9]{8,15}$",
55	            message = "Phone number must be E.164: '+' followed by 8 to 15 digits")
56	    private String telephone;
57	
58	    @Column(name = "email")
59	    private String email;
60	
61	    @Column(name = "registration_date")
62	    private LocalDate registrationDate;
63	
64	    @Column(name = "birth_date")
65	    private LocalDate birthDate;
66	
67	    @Column(name = "customer_code")
68	    private String customerCode;
69	
70	    @Column(name = "membership_number")
71	    private String membershipNumber;
72	
73	    @Column(name = "household_id")
74	    private String householdId;
75	
76	    @Column(name = "namesake_count")
77	    private Integer namesakeCount;
78	
79	    @Column(name = "possible_duplicate")
80	    private Boolean possibleDuplicate;
81	
82	    @Column(name = "possible_duplicate_of")
83	    private Integer possibleDuplicateOf;
84	
85	    @Transient
86	    private Boolean bulkSignupWarning;
87	
88	    @Transient
89	    private Integer householdSize;
90	
91	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
92	    private Set<Pet> pets;
93	
94	    public String getAddress() {
95	        return this.address;
96	    }
97	
98	    public void setAddress(String address) {
99	        this.address = address;
100	    }
101	
102	    public String getCity() {
103	        return this.city;
104	    }
105	
106	    public void setCity(String city) {
107	        this.city = city;
108	    }
109	
110	    public String getPostcode() {
111	        return this.postcode;
112	    }
113	
114	    public void setPostcode(String postcode) {
115	        this.postcode = postcode;
116	    }
117	
118	    public String getTelephone() {
119	        return this.telephone;
120	    }
121	
122	    public void setTelephone(String telephone) {
123	        this.telephone = telephone;
124	    }
125	
126	    public String getEmail() {
127	        return this.email;
128	    }
129	
130	    public void setEmail(String email) {
131	        this.email = email;
132	    }
133	
134	    public LocalDate getRegistrationDate() {
135	        return this.registrationDate;
136	    }
137	
138	    public void setRegistrationDate(LocalDate registrationDate) {
139	        this.registrationDate = registrationDate;
140	    }
141	
142	    public LocalDate getBirthDate() {
143	        return this.birthDate;
144	    }
145	
146	    public void setBirthDate(LocalDate birthDate) {
147	        this.birthDate = birthDate;
148	    }
149	
150	    /**
151	     * The owner's age band, derived at response time from {@link #birthDate} against
152	     * {@link #registrationDate}: {@code MINOR} when under 18 years old, {@code ADULT} when 18 to 64,
153	     * and {@code SENIOR} when 65 or over. {@code null} when the owner has no birth date (or no
154	     * registration date to compute against). Not persisted.
155	     */
156	    public String getAgeBand() {
157	        if (this.birthDate == null || this.registrationDate == null) {
158	            return null;
159	        }
160	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
161	        if (age < 18) {
162	            return "MINOR";
163	        }
164	        if (age < 65) {
165	            return "ADULT";
166	        }
167	        return "SENIOR";
168	    }
169	
170	    public String getCustomerCode() {
171	        return this.customerCode;
172	    }
173	
174	    public void setCustomerCode(String customerCode) {
175	        this.customerCode = customerCode;
176	    }
177	
178	    public String getMembershipNumber() {
179	        return this.membershipNumber;
180	    }
181	
182	    public void setMembershipNumber(String membershipNumber) {
183	        this.membershipNumber = membershipNumber;
184	    }
185	
186	    public String getHouseholdId() {
187	        return this.householdId;
188	    }
189	
190	    public void setHouseholdId(String householdId) {
191	        this.householdId = householdId;
192	    }
193	
194	    public Integer getNamesakeCount() {
195	        return this.namesakeCount;
196	    }
197	
198	    public void setNamesakeCount(Integer namesakeCount) {
199	        this.namesakeCount = namesakeCount;
200	    }
201	
202	    /**
203	     * Whether this owner, when created, was a possible (soft) duplicate of an earlier owner, keyed
204	     * off the shared {@link #getHouseholdId() householdId} (same lastName and postcode). A declared
205	     * household member (created with {@code sharesHousehold} true) is never flagged; any other owner
206	     * joining an existing household is rejected 409 instead. {@code false} when no such earlier owner
207	     * existed. Assigned at creation.
208	     */
209	    public Boolean getPossibleDuplicate() {
210	        return this.possibleDuplicate;
211	    }
212	
213	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
214	        this.possibleDuplicate = possibleDuplicate;
215	    }
216	
217	    /**
218	     * The id of the earlier owner this owner is a possible duplicate of (the earliest such match),
219	     * or {@code null} when {@link #getPossibleDuplicate()} is false. Assigned at creation.
220	     */
221	    public Integer getPossibleDuplicateOf() {
222	        return this.possibleDuplicateOf;
223	    }
224	
225	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
226	        this.possibleDuplicateOf = possibleDuplicateOf;
227	    }
228	
229	    /**
230	     * Whether more than 80 owners had already been created on this owner's registration day,
231	     * derived at response time and not persisted. {@code true} triggers a bulk-signup warning
232	     * in the response.
233	     */
234	    public Boolean getBulkSignupWarning() {
235	        return this.bulkSignupWarning;
236	    }
237	
238	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
239	        this.bulkSignupWarning = bulkSignupWarning;
240	    }
241	
242	    /**
243	     * The number of owners in this owner's household (owners sharing the same
244	     * {@link #householdId}), derived at response time and not persisted.
245	     */
246	    public Integer getHouseholdSize() {
247	        return this.householdSize;
248	    }
249	
250	    public void setHouseholdSize(Integer householdSize) {
251	        this.householdSize = householdSize;
252	    }
253	
254	    /**
255	     * The owner's membership points, derived at response time. Starts at {@code 0}, plus 2 when an
256	     * email is present, plus 1 when {@link #namesakeCount} is 0, plus 2 when the
257	     * {@link #getHouseholdSize() household} has 3 or more members, plus 3 when tenure exceeds 365 days
258	     * (measured from the {@link #registrationDate}).
259	     */
260	    public Integer getMembershipPoints() {
261	        int points = 0;
262	        if (this.email != null && !this.email.isEmpty()) {
263	            points += 2;
264	        }
265	        if (this.namesakeCount != null && this.namesakeCount == 0) {
266	            points += 1;
267	        }
268	        if (this.householdSize != null && this.householdSize >= 3) {
269	            points += 2;
270	        }
271	        if (getTenureDays() > 365) {
272	            points += 3;
273	        }
274	        return points;
275	    }
276	
277	    /**
278	     * The owner's numeric membership level, mapped from {@link #getMembershipPoints() membershipPoints}:
279	     * {@code 1} for 0-1 points, {@code 2} for 2-3 points, {@code 3} for 4-5 points, and {@code 4} for
280	     * 6 or more points.
281	     */
282	    public Integer getMembershipLevel() {
283	        int points = getMembershipPoints();
284	        if (points <= 1) {
285	            return 1;
286	        }
287	        if (points <= 3) {
288	            return 2;
289	        }
290	        if (points <= 5) {
291	            return 3;
292	        }
293	        return 4;
294	    }
295	
296	    /**
297	     * The owner's tenure in whole days, measured from the {@link #registrationDate} to today; zero
298	     * when the registration date is absent or in the future.
299	     */
300	    private long getTenureDays() {
301	        if (this.registrationDate == null) {
302	            return 0;
303	        }
304	        long days = ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
305	        return Math.max(days, 0);
306	    }
307	
308	    /** Fixed city-to-region table used to derive {@link #getLocality()}. */
309	    private static final Map<String, String> CITY_REGION = Map.of(
310	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
311	
312	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive {@link #getLocality()}. */
313	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
314	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
315	
316	    /**
317	     * The fixed city-to-region mapping ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
318	     * {@code Brisbane -> QLD}): the region for {@code city}, or {@code null} when the city is not in
319	     * the table. Used only by postcode validation, which branches on "known region or not" by testing
320	     * for {@code null} before range-checking the postcode.
321	     */
322	    public static String regionOf(String city) {
323	        return CITY_REGION.get(city);
324	    }
325	
326	    /**
327	     * The region whose fixed postcode range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
328	     * {@code QLD 4000-4099}) contains {@code postcode}, or {@code null} when {@code postcode} is
329	     * absent, not a 4-digit number, or in no known range.
330	     */
331	    public static String regionOfPostcode(String postcode) {
332	        if (postcode == null || postcode.isEmpty()) {
333	            return null;
334	        }
335	        int value;
336	        try {
337	            value = Integer.parseInt(postcode);
338	        } catch (NumberFormatException ex) {
339	            return null;
340	        }
341	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
342	            int[] range = entry.getValue();
343	            if (value >= range[0] && value <= range[1]) {
344	                return entry.getKey();
345	            }
346	        }
347	        return null;
348	    }
349	
350	    /**
351	     * The owner's region, derived at response time from the {@code REGION} prefix of the
352	     * {@link #customerCode} (the segment before the first {@code '-'}). Because the customer code is
353	     * assigned as {@code <REGION>-<HASH8>} with REGION taken from the postcode, the locality follows
354	     * the same region-and-hash identity as the customer code. {@code UNKNOWN} when the owner has no
355	     * customer code.
356	     */
357	    public String getLocality() {
358	        if (this.customerCode == null) {
359	            return "UNKNOWN";
360	        }
361	        int dash = this.customerCode.indexOf('-');
362	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
363	    }
364	
365	    /**
366	     * The owner's preferred contact channel, derived at response time: {@code EMAIL} when an
367	     * email is present, otherwise {@code PHONE}. Not persisted.
368	     */
369	    public String getContactPreference() {
370	        return (this.email != null && !this.email.isEmpty()) ? "EMAIL" : "PHONE";
371	    }
372	
373	    /**
374	     * A single Luhn check digit (0-9) derived at response time over the digits contained in
375	     * {@link #customerCode} (non-digit characters are ignored), or {@code null} when the owner
376	     * has no customer code. Computed with the standard Luhn algorithm — doubling every second
377	     * digit from the right, subtracting 9 from any result over 9, and taking
378	     * {@code (10 - sum % 10) % 10}. Not persisted.
379	     */
380	    public Integer getCheckDigit() {
381	        if (this.customerCode == null) {
382	            return null;
383	        }
384	        int sum = 0;
385	        boolean dbl = true;
386	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
387	            char c = this.customerCode.charAt(i);
388	            if (c < '0' || c > '9') {
389	                continue;
390	            }
391	            int d = c - '0';
392	            if (dbl) {
393	                d *= 2;
394	                if (d > 9) {
395	                    d -= 9;
396	                }
397	            }
398	            sum += d;
399	            dbl = !dbl;
400	        }
401	        return (10 - (sum % 10)) % 10;
402	    }
403	
404	    /**
405	     * A display-only derived string composing the owner's canonical contact and household values:
406	     * {@code normalizedTelephone|email|householdId}, joined with '|'. The telephone is stored in
407	     * canonical E.164 form and the email lower-cased; an absent email or householdId contributes an
408	     * empty segment. Derived at response time and exposed as a read-only response field only — it
409	     * drives no check. Duplicate detection is purely household-based (see
410	     * {@code CheckOwnerHouseholdUnique}, which compares {@link #getHouseholdId() householdId}); this
411	     * key is not consulted. Not persisted.
412	     */
413	    public String getIdentityKey() {
414	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
415	    }
416	
417	    private static String keyPart(String value) {
418	        return value == null ? "" : value;
419	    }
420	
421	    /**
422	     * The stored E.164 {@link #telephone} formatted for humans: the country code, a space, then the
423	     * national digits (everything after the country code) grouped in threes and space-separated —
424	     * e.g. {@code +61412345678} becomes {@code +61 412 345 678}. The country code is recognised for
425	     * '+61' (2 digits) and '+1' (1 digit); any other prefix falls back to a 2-digit country code.
426	     * {@code null} when the telephone is absent or not a valid E.164 value. Derived at response time
427	     * and not persisted; the raw {@link #getTelephone() telephone} stays in E.164 form.
428	     */
429	    public String getTelephoneDisplay() {
430	        if (this.telephone == null || !this.telephone.matches("\\+\\d{8,15}")) {
431	            return null;
432	        }
433	        String digits = this.telephone.substring(1);
434	        int countryCodeLength;
435	        if (digits.startsWith("61")) {
436	            countryCodeLength = 2;
437	        }
438	        else if (digits.startsWith("1")) {
439	            countryCodeLength = 1;
440	        }
441	        else {
442	            countryCodeLength = 2;
443	        }
444	        String countryCode = digits.substring(0, countryCodeLength);
445	        String national = digits.substring(countryCodeLength);
446	        StringBuilder display = new StringBuilder("+").append(countryCode);
447	        for (int i = 0; i < national.length(); i += 3) {
448	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
449	        }
450	        return display.toString();
451	    }
452	
453	    protected Set<Pet> getPetsInternal() {
454	        if (this.pets == null) {
455	            this.pets = new HashSet<>();
456	        }
457	        return this.pets;
458	    }
459	
460	    protected void setPetsInternal(Set<Pet> pets) {
461	        this.pets = pets;
462	    }
463	
