465	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
466	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
467	        return Collections.unmodifiableList(sortedPets);
468	    }
469	
470	    public void setPets(List<Pet> pets) {
471	        this.pets = new HashSet<>(pets);
472	    }
473	
